const $ = (s, root=document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={fit:'<path d="M9 3 3 6l3 5 2-1v11h8V10l2 1 3-5-6-3a3 3 0 0 1-6 0Z"/>',size:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M7 5v5m5-5v8m5-8v5"/>',analytics:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',inventory:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 0v11l9 4 9-4V7M12 11v11"/>',qr:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h3v3h3v3h-6zm3-3h3M12 3v3m0 6h3M3 12h6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',spark:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3Z"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[k]||icons.fit}</svg>`;
let state={view:'fit',store:new URLSearchParams(location.search).get('store')||null,products:[],selected:null,photo:null,result:null,filter:'all',search:'',busy:false,fitError:null,progress:null};
let bootstrap, kiosk=location.pathname==='/kiosk', kioskTimer;
async function api(path,options={}){const opts={...options,headers:{'X-CSRF-Token':bootstrap?.csrf||'',...options.headers}};if(opts.body && !(opts.body instanceof FormData)){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}const r=await fetch('/api'+path,opts);const text=await r.text();let data={};if(text){try{data=JSON.parse(text)}catch{throw Error(r.ok?'The server returned an unexpected response.':'Something went wrong. Please try again.')}}if(!r.ok)throw Error(data.error||'Something went wrong. Please try again.');return data}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function refresh(){const previousUser=bootstrap?.user?.id;bootstrap=await api('/bootstrap');if(!state.store||!bootstrap.stores.some(s=>s.id===state.store)||(previousUser!==bootstrap.user?.id&&!new URLSearchParams(location.search).has('store'))){state.store=bootstrap.user?.store||'demo'}await loadProducts();render()}
function rememberStore(id){state.store=id;state.search='';state.filter='all';state.result=null;state.fitError=null;const url=new URL(location.href);url.searchParams.set('store',id);history.replaceState(null,'',url.pathname+url.search+url.hash)}
async function loadProducts(){const data=await api('/products?store='+encodeURIComponent(state.store));state.products=data.products;state.storeInfo=data.store;if(!state.products.some(p=>p.id===state.selected))state.selected=state.products[0]?.id||null}
function selected(){return state.products.find(p=>p.id===state.selected)}
function head(title,subtitle,extra=''){return `<div class="page-head"><div><div class="eyebrow">${state.view==='fit'?'YOUR PERSONAL FITTING ROOM':'AI-FIT / '+esc(state.view)}</div><h1>${title}</h1><p class="subtle">${subtitle}</p></div>${extra}</div>`}
function render(){document.body.classList.toggle('kiosk',kiosk);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><b>ai</b> AI-FIT</div><div class="eyebrow">Discover your fit</div><nav class="nav" aria-label="Main navigation">${[['fit','Virtual try-on'],['size','Find my size'],['analytics','Store insights'],['inventory','Inventory'],['qr','In-store access']].map(([id,name])=>`<button data-view="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(id)}${name}</button>`).join('')}</nav><div class="side-bottom"><b>A little more confidence.</b><span>A better way to find your fit.</span><p>Made for Pakistan’s<br>independent fashion stores.</p></div></aside><main class="main"><header class="topbar"><select class="store-select" id="store-select" aria-label="Choose store">${bootstrap.stores.map(s=>`<option value="${esc(s.id)}" ${s.id===state.store?'selected':''}>${esc(s.name)}${s.id==='demo'?' · Sample catalog':''}</option>`).join('')}</select><div class="top-actions"><span class="badge"><i class="dot"></i>Private photo processing</span>${bootstrap.user?`<span class="avatar">${esc(bootstrap.user.name[0])}</span><span class="username">${esc(bootstrap.user.name)}</span><button class="plain" id="logout">Sign out</button>`:'<button id="signin">Sign in</button>'}</div></header><div class="content" id="content"></div></main></div>${kiosk?(bootstrap.user?'<button class="kiosk-exit" id="reset-kiosk">End session</button>':'<button class="kiosk-exit" id="kiosk-signin">Sign in</button>'):''}`;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$('#store-select').onchange=async e=>{rememberStore(e.target.value);await loadProducts();render()};if($('#signin'))$('#signin').onclick=()=>authDialog();if($('#logout'))$('#logout').onclick=logout;if($('#reset-kiosk'))$('#reset-kiosk').onclick=resetKiosk;if($('#kiosk-signin'))$('#kiosk-signin').onclick=()=>authDialog();
({fit:renderFit,size:renderSize,analytics:renderAnalytics,inventory:renderInventory,qr:renderQr}[state.view]||renderFit)();}
function productArt(p){return p.image?`<img src="/media/${esc(p.image)}" alt="${esc(p.name)}">`:`<svg viewBox="0 0 140 150" aria-label="Sample garment illustration"><g fill="${esc(p.color)}" stroke="#20352d" stroke-opacity=".2" stroke-width="1.5">${p.category==='lower'?'<path d="M39 20h62l8 115H78l-8-80-8 80H31Z"/><path d="M39 30h62M70 20v35" fill="none"/>':`<path d="M49 19 21 31 6 66l24 12 12-23-4 ${p.category==='overall'?'83':'62'}h64l-4-${p.category==='overall'?'83':'62'} 12 23 24-12-15-35-28-12-21 7Z"/><path d="m49 19 21 18 21-18M70 37v${p.category==='overall'?'96':'75'}" fill="none"/>`}</g></svg><span class="sample">SAMPLE</span>`}
function renderFit(){$('#content').innerHTML=head('See it. Try it. Make it yours.','Choose a piece, add your photo, and find your perfect fit.','<span class="badge">01 / THE FITTING ROOM</span>')+`<div class="steps"><span><b>1</b> Add your photo</span><span><b>2</b> Choose a garment</span><span><b>3</b> See your look</span></div><div class="fitting-grid"><section class="panel"><div class="panel-head"><h2>Your photo</h2><span class="subtle">01</span></div><div class="upload-area" id="drop-zone">${state.photo?`<img src="${esc(state.photo.url)}" alt="Your uploaded photo">`:`<div class="upload-prompt"><span class="upload-icon">${icon('upload')}</span><b>Start with you.</b><p>${selected()?.category==='upper'?'Use a front-facing photo with your shoulders, waist and arms visible.': 'Use a clear, front-facing photo with your head, hands and feet visible.'}<br>JPEG or PNG, up to 12 MB.</p><button id="choose-photo">Choose a photo</button><span class="subtle">or drop it here</span></div>`}</div><input type="file" id="photo-input" accept="image/jpeg,image/png" hidden><label class="consent"><input type="checkbox" id="photo-consent" ${state.photo?'checked':''}>I have permission to use this photo and consent to AI processing.</label><div class="guidance"><div>✓ Face the camera in good lighting</div><div>✓ Keep your arms away from your body</div><div>✓ Wear close-fitting clothing</div>${state.photo?'<button id="remove-photo">Remove photo</button>':''}</div></section><section class="panel"><div class="panel-head"><h2>Your new look</h2><span class="pill">${state.busy?'Generating…':state.result?'Preview ready':'Preview'}</span></div><div class="result-stage" aria-busy="${state.busy?'true':'false'}">${state.busy?progressPanel():state.result?`<img src="${esc(state.result.url)}" alt="AI-generated try-on result">`:`<div class="result-empty">${icon('spark')}<h3>A new look,<br>still you.</h3><p>Your virtual try-on will appear here once your photo and garment are ready.</p></div>`}</div><div class="result-footer"><button class="primary" id="generate" ${state.busy||state.uploading?'disabled':''}>${state.busy?'<span class="spinner"></span>Creating your look…':state.uploading?'Uploading photo…':'Generate my look'}</button>${!state.busy&&state.progress?progressPanel():''}${state.fitError?`<p class="inline-error" role="alert">${esc(state.fitError)}</p>`:''}${state.result?`<div class="toolbar"><a href="${esc(state.result.url)}?download=1" download>Save image</a><button class="link-button" id="share-result">Share image</button></div><p>Try-on ID: ${esc(state.result.tryon)}</p>`:''}<p>${bootstrap.tryon_ready?'Successful try-ons also contribute to aggregate store preferences using a store-specific account identifier. AI-generated previews illustrate appearance; use size recommendations to assess fit.':'Photo generation is awaiting GPU service setup. You can explore the catalog and find your size.'}</p></div></section><section class="panel catalog-panel"><div class="panel-head"><h2>The collection</h2><span class="subtle">${state.products.length} pieces</span></div><div class="catalog-controls"><input id="search" placeholder="Search garments…" aria-label="Search garments" value="${esc(state.search)}"><div class="filters">${[['all','All'],['upper','Tops'],['lower','Bottoms'],['overall','Full outfits']].map(([id,label])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}">${label}</button>`).join('')}</div></div>${selected()?.category==='overall'?'<p class="outfit-photo-tip">For full outfits, use a product photo showing the whole set, including trousers and any dupatta.</p>':''}<div class="catalog-list" id="catalog-list"></div></section></div><div class="notice">${icon('size').replace('<svg','<svg width="25" height="25"')}<span><strong>Looks good. Fits even better.</strong> Get a size recommendation based on your measurements. <button class="link-button" id="go-size">Find my size →</button></span></div><p class="footer-note">Personal photos expire after 24 hours. Remove yours anytime. Sample illustrations cannot be used for AI try-on.</p>`;
renderCatalog();$('#search').oninput=e=>{state.search=e.target.value;renderCatalog()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderFit()});$('#go-size').onclick=()=>{state.sizeCategory=selected()?.category||'upper';state.sizeProduct=state.selected;state.view='size';render()};if($('#choose-photo'))$('#choose-photo').onclick=()=>$('#photo-input').click();$('#photo-input').onchange=e=>uploadPhoto(e.target.files[0]);const drop=$('#drop-zone');drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();uploadPhoto(e.dataTransfer.files[0])};if($('#remove-photo'))$('#remove-photo').onclick=async()=>{try{await api('/uploads/'+state.photo.id,{method:'DELETE'});state.photo=null;state.result=null;state.fitError=null;if(!state.busy)state.progress=null;renderFit()}catch(e){toast(e.message)}};$('#generate').onclick=generate;if($('#share-result'))$('#share-result').onclick=shareResult;}
function renderCatalog(){const list=state.products.filter(p=>(state.filter==='all'||p.category===state.filter)&&p.name.toLowerCase().includes(state.search.toLowerCase()));$('#catalog-list').innerHTML=list.length?list.map(p=>`<button class="product ${state.selected===p.id?'selected':''}" data-product="${esc(p.id)}" aria-pressed="${state.selected===p.id}"><div class="product-art">${productArt(p)}</div><div class="product-copy"><b>${esc(p.name)}</b><span>PKR ${p.price.toLocaleString()}</span></div></button>`).join(''):'<div class="empty">No garments found.</div>';document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.product;state.result=null;state.fitError=null;if(!state.busy)state.progress=null;renderFit()})}
async function uploadPhoto(file){
  if(!file)return;if(!bootstrap.user){authDialog();return}
  if(!$('#photo-consent').checked){toast('Please confirm photo consent first.');return}
  const token=Symbol('upload'),owner=bootstrap.user.id;state.activeUpload=token;state.uploading=true;
  const button=$('#generate');if(button){button.disabled=true;if(!state.busy)button.textContent='Uploading photo…'}
  const form=new FormData();form.append('file',file);form.append('kind','person');form.append('consent','true');
  try{
    const photo=await api('/uploads',{method:'POST',body:form});
    if(state.activeUpload!==token||bootstrap.user?.id!==owner)return;
    state.photo=photo;state.result=null;state.fitError=null;if(!state.busy)state.progress=null;toast('Your photo is ready.');
  }catch(e){if(state.activeUpload===token&&bootstrap.user?.id===owner)toast(e.message)}
  finally{if(state.activeUpload===token){state.uploading=false;if(state.view==='fit')renderFit()}}
}
let generationPoll, generationClock;
function forgetGeneration(){generationPoll?.abort();clearInterval(generationClock);generationPoll=null;generationClock=null;state.progress=null;state.busy=false;state.activeUpload=null;state.uploading=false}
function progressPanel(){return `<div id="generation-progress"><div id="generation-progress-body">${TryOnProgress.markup(state.progress)}</div><span id="progress-announcement" class="progress-announcement" role="status" aria-live="polite"></span></div>`}
function paintProgress(){
  if(state.view!=='fit'||!state.progress)return;
  const body=$('#generation-progress-body');if(body)body.innerHTML=TryOnProgress.markup(state.progress);
  const announcement=$('#progress-announcement'),text=TryOnProgress.view(state.progress,performance.now()).stage;
  if(announcement&&announcement.textContent!==text)announcement.textContent=text;
}
async function pollGeneration(id,owner,signal){
  while(!signal.aborted&&state.busy&&state.progress?.id===id&&bootstrap.user?.id===owner){
    try{
      const update=await api('/tryon-progress/'+id,{signal,cache:'no-store'});
      if(signal.aborted||state.progress?.id!==id||bootstrap.user?.id!==owner)return;
      const previous=state.progress;
      state.progress={...previous,...update,percent:Math.max(previous.percent,Math.min(99,Number(update.percent)||0)),observed:performance.now()};
      if(update.tracking_available===false)state.progress.stage=previous.stage;
      // Only the saved-result POST response can finish the UI at 100%.
      if(update.status==='complete')state.progress={...state.progress,status:'running',stage:'saving',percent:99};
      if(update.status==='failed')state.progress={...state.progress,status:'running',stage:previous.stage};
      paintProgress();
    }catch(error){if(signal.aborted)return;}
    await new Promise(resolve=>{const timer=setTimeout(done,1500);function done(){clearTimeout(timer);signal.removeEventListener('abort',done);resolve()}signal.addEventListener('abort',done,{once:true})});
  }
}
async function generate(){
  if(state.busy)return;if(state.uploading){toast('Please wait for your photo to finish uploading.');return}if(!bootstrap.user){authDialog();return}if(!state.photo){toast('Add your photo first.');return}
  if(!selected()?.image){toast('Choose a garment with a real product photo. Sample illustrations cannot be generated.');return}
  const bytes=crypto.getRandomValues(new Uint8Array(16)),request_id=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
  const input={photo:state.photo.id,product:state.selected,request_id},owner=bootstrap.user.id;
  const matches=()=>state.photo?.id===input.photo&&state.selected===input.product&&bootstrap.user?.id===owner;
  state.busy=true;state.result=null;state.fitError=null;
  state.progress={id:request_id,garment:selected().name,status:'running',stage:'starting',percent:0,elapsed_seconds:0,remaining_seconds:null,observed:performance.now()};
  const started=performance.now();renderFit();$('#generation-progress')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  const pollController=new AbortController(),clock=setInterval(paintProgress,1000);
  generationPoll=pollController;generationClock=clock;
  pollGeneration(request_id,owner,pollController.signal);
  try{
    const result=await api('/tryon',{method:'POST',body:input});
    if(generationPoll!==pollController)return;
    if(matches()){
      state.result=result;state.progress={...state.progress,status:'complete',stage:'complete',percent:100,elapsed_seconds:(performance.now()-started)/1000,observed:performance.now()};
    }else{state.progress=null;toast('Selection changed during generation. Generate again for your current garment.')}
  }catch(e){
    if(generationPoll!==pollController)return;
    if(matches()){state.fitError=e.message;state.progress={...state.progress,status:'failed',elapsed_seconds:(performance.now()-started)/1000,observed:performance.now()}}else state.progress=null;
    toast(e.message);
  }finally{
    pollController.abort();clearInterval(clock);
    if(generationPoll===pollController){state.busy=false;if(state.view==='fit')renderFit()}
  }
}
function commerceDetails(r){return `<section class="panel section-space sales-chart"><div class="panel-head"><h2>Sales trend</h2><span class="badge">Last 7 days / UTC</span></div><div class="sales-summary"><div><span>Order value</span><strong>PKR ${Number(r.sales_preview.value).toLocaleString()}</strong></div><div><span>Average order value</span><strong>PKR ${Math.round(r.sales_preview.value/r.sales_preview.orders).toLocaleString()}</strong></div></div><p class="subtle panel-body">Illustrative sales figures; not recorded transactions.</p>${trendGraph(r.sales_preview.daily_orders,"Sample sales")}</section>`}

async function shareResult(){try{if(!state.result)return;const r=await fetch(state.result.url);if(!r.ok)throw Error('Image unavailable');const file=new File([await r.blob()],'ai-fit.jpg',{type:'image/jpeg'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'My AI-FIT look'});else{toast('Sharing is not supported here. Use Save image.')}}catch(e){if(e.name!=='AbortError')toast('Could not share this image. Use Save image.')}}
function productSelect(){return `<label class="field full">Garment<select name="product" id="size-product">${state.products.map(p=>`<option value="${esc(p.id)}" ${p.id===state.selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`}
const sizeRequired={upper:['chest','waist'],lower:['waist','hips'],overall:['chest','waist','hips']};
const sizeOptional={upper:['shoulder','sleeve'],lower:['inseam','thigh'],overall:['shoulder','sleeve','inseam','thigh']};
const sizeLabels={upper:'Upper Body',lower:'Lower Body',overall:'Full Outfit',chest:'Chest / bust',waist:'Waist',hips:'Hips',shoulder:'Shoulder width',sleeve:'Arm / sleeve length',inseam:'Inseam',thigh:'Thigh'};
const sizeLimits={chest:[20,75],waist:[16,75],hips:[20,80],shoulder:[8,30],sleeve:[10,40],inseam:[15,45],thigh:[10,45]};
function renderSize(){
 const category=state.sizeCategory||(selected()?.category||'upper');
 state.sizeCategory=category;
 const products=state.products.filter(p=>p.category===category);
 if(!products.some(p=>p.id===state.sizeProduct))state.sizeProduct=products.find(p=>p.id===state.selected)?.id||products[0]?.id||'';
 const chart=state.storeInfo?.charts?.[category]||{};
 const fields=[...sizeRequired[category],...sizeOptional[category].filter(k=>Object.values(chart).some(row=>k in row))];
 $('#content').innerHTML=head('A size that makes sense.','Use your body measurements and the selected garment’s chart.')+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Your measurements</h2><span class="pill">inches / kg</span></div><form id="size-form" class="panel-body stack"><div class="form-grid"><label class="field full">Body category<select id="size-category" name="category">${Object.keys(sizeRequired).map(c=>`<option value="${c}" ${c===category?'selected':''}>${sizeLabels[c]}</option>`).join('')}</select></label><label class="field full">Garment<select name="product" id="size-product" ${products.length?'':'disabled'}>${products.length?products.map(p=>`<option value="${esc(p.id)}" ${p.id===state.sizeProduct?'selected':''}>${esc(p.name)}</option>`).join(''):'<option value="">No garments in this category</option>'}</select></label><p class="field full"><b>${sizeLabels[category]}</b></p><label class="field">Height (feet)<input name="height_feet" type="number" min="3" max="7" step="1" placeholder="5" required></label><label class="field">Height (inches)<input name="height_inches" type="number" min="0" max="11.99" step="0.01" placeholder="8" required></label><label class="field">Weight (kg)<input name="weight" type="number" min="25" max="250" step="0.1" required></label>${fields.map(k=>`<label class="field">${sizeLabels[k]} (in)<input name="${k}" type="number" min="${sizeLimits[k][0]}" max="${sizeLimits[k][1]}" step="0.01" required></label>`).join('')}</div><p class="subtle">Measure chest/bust and hips around the fullest part, waist at its natural level. Keep the tape level without pulling tight. Shoulder width is across the back; sleeve is shoulder to wrist; inseam is crotch to ankle. Enter body measurements, not flat garment widths.</p><p class="subtle">${esc(state.storeInfo?.chart_status||'illustrative')} chart. Height and weight are collected for context; the chart estimate uses the relevant body dimensions.</p><label class="consent" style="padding:0"><input name="consent" type="checkbox" required>I consent to processing these measurements. Raw measurements are not retained.</label><button class="primary" ${products.length?'':'disabled'}>Find my size</button><div id="size-error" class="inline-error" role="alert"></div></form></section><section id="size-output"><div class="panel empty"><h2>Your fit, explained.</h2><p>Choose a garment to see its relevant measurement fields.</p><p class="subtle">Chart estimates are available. Validated fitting confidence is not available.</p></div></section></div>`;
 const changeSelection=(key,value)=>{const saved=Object.fromEntries(new FormData($('#size-form')));state[key]=value;renderSize();for(const [name,v] of Object.entries(saved)){if(['product','category','consent'].includes(name))continue;const input=$(`#size-form [name="${name}"]`);if(input)input.value=v;}};
 $('#size-category').onchange=e=>changeSelection('sizeCategory',e.target.value);
 $('#size-product').onchange=e=>changeSelection('sizeProduct',e.target.value);
 $('#size-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),body={product:form.get('product'),category,units:'in',consent:form.get('consent')==='on'};for(const k of ['height_feet','height_inches','weight',...fields])body[k]=Number(form.get(k));const button=e.target.querySelector('button');button.disabled=true;try{const r=await api('/size',{method:'POST',body});if(state.view!=='size'||state.sizeCategory!==category||state.sizeProduct!==body.product)return;$('#size-output').innerHTML=`<div class="size-result"><div>Your chart estimate</div><div class="big">${esc(r.size)}</div><span class="fit-tag">${esc(r.fit)} · chart-estimated</span><p>${esc(r.method)}</p><p>${r.confidence===null?'Fitting confidence unavailable.':esc(r.confidence)+'% calibrated size-label model support; not a fit guarantee.'}</p></div><div class="panel section-space"><div class="panel-head"><h2>${sizeLabels[r.category]} body chart</h2><span>inches</span></div><p class="panel-body subtle">${esc(r.chart_status)}</p><div class="table-wrap"><table><thead><tr><th>Size</th>${r.fields.map(k=>`<th>${sizeLabels[k]}</th>`).join('')}</tr></thead><tbody>${r.comparisons.map(c=>`<tr ${c.size===r.size?'style="background:#edf4e9"':''}><td>${esc(c.size)}${c.available?'':' · unavailable'}</td>${r.fields.map(k=>`<td>${c[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="panel-body">${esc(r.notes)}</p></div>`;$('#size-error').textContent=''}catch(err){if(state.view==='size'&&state.sizeCategory===category&&state.sizeProduct===body.product)$('#size-error').textContent=err.message}finally{button.disabled=false}};
}
const passwordEye = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M2 12s3.6-6 10-6 10 6 10 6-3.6 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/><path class="eye-slash" d="m4 4 16 16"/></svg>';
function passwordField(label, autocomplete){
  return `<div class="field password-field"><label for="account-password">${label}</label><div class="password-control">
    <input id="account-password" type="password" name="password" minlength="10" maxlength="128" autocomplete="${autocomplete}" required>
    <button type="button" class="password-toggle" aria-controls="account-password" aria-label="Show password" title="Show password">${passwordEye}</button>
  </div></div>`;
}
function authDialog(register=false){modal('Welcome to AI-FIT',`<form id="auth-form">${register?'<label class="field">Your name<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label class="field">Email<input type="email" name="email" autocomplete="email" required></label>${passwordField('Password', register?'new-password':'current-password')}<button class="primary">${register?'Create account':'Sign in'}</button><button type="button" class="plain" id="switch-auth">${register?'Already have an account? Sign in':'New here? Create an account'}</button>${register?'':'<button type="button" class="plain" id="forgot-password">Forgot password?</button>'}<div id="auth-error" class="inline-error" role="alert"></div></form>`);if($('#switch-auth'))$('#switch-auth').onclick=()=>authDialog(!register);if($('#forgot-password'))$('#forgot-password').onclick=()=>passwordResetDialog('', $('#auth-form').elements.email.value);$('#auth-form').onsubmit=async e=>{e.preventDefault();try{await api('/auth/'+(register?'register':'login'),{method:'POST',body:Object.fromEntries(new FormData(e.target))});$('#modal').close();await refresh()}catch(err){$('#auth-error').textContent=err.message}}}
function passwordResetDialog(token='', email=''){
  modal(token?'Choose a new password':'Reset your password', `<form id="reset-form" class="stack">
    ${token?passwordField('New password', 'new-password'):
      `<label class="field">Email<input type="email" name="email" value="${esc(email)}" autocomplete="email" required></label>`}
    <button class="primary" type="submit">${token?'Update password':'Send reset link'}</button>
    <button class="plain" type="button" id="back-to-signin">Back to sign in</button>
    <div class="inline-error" role="alert"></div><div role="status"></div>
  </form>`);
  $('#back-to-signin').onclick=()=>authDialog();
  $('#reset-form').onsubmit=async event=>{
    event.preventDefault();
    const form=event.currentTarget;
    const submit=form.querySelector('[type="submit"]');
    const error=form.querySelector('[role="alert"]');
    const body=Object.fromEntries(new FormData(form));
    if(token)body.token=token;
    submit.disabled=true;
    error.textContent='';
    try{
      await api('/auth/'+(token?'reset-password':'forgot-password'),{method:'POST',body});
      if(token){
        await refresh();
        if(form.isConnected && $('#modal').open)authDialog();
        toast('Password updated. Sign in with your new password.');
      }else{
        form.querySelector('[role="status"]').textContent='If an account exists for that email, a reset link will be sent.';
      }
    }catch(err){error.textContent=err.message}finally{submit.disabled=false}
  };
}
function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">×</button></div>${body}`;$('#close-modal').onclick=()=>d.close();const toggle=d.querySelector('.password-toggle');if(toggle)toggle.onclick=()=>{
  const input=d.querySelector('#account-password');
  const show=input.type==='password';
  input.type=show?'text':'password';
  const label=show?'Hide password':'Show password';
  toggle.setAttribute('aria-label',label);
  toggle.title=label;
};if(!d.open)d.showModal()}
async function logout(){await api('/auth/logout',{method:'POST'});forgetGeneration();state.photo=null;state.result=null;state.fitError=null;await refresh()}
function retailerGate(){if(!bootstrap.user){$('#content').innerHTML='<div class="auth-gate"><h2>Your store, in focus.</h2><p>Sign in to manage your collection and explore your store’s performance.</p><button class="primary" id="gate-signin">Sign in</button></div>';$('#gate-signin').onclick=()=>authDialog();return false}if(!bootstrap.user.store){$('#content').innerHTML='<div class="auth-gate"><h2>Bring your store to AI-FIT.</h2><p>Create your store to upload inventory, set size charts, and track real fitting-room activity.</p><form id="create-store" class="stack"><input name="name" placeholder="Store name" aria-label="Store name" required maxlength="80"><button class="primary">Create my store</button></form></div>';$('#create-store').onsubmit=async e=>{e.preventDefault();try{const r=await api('/store',{method:'POST',body:Object.fromEntries(new FormData(e.target))});state.store=r.store.id;await refresh()}catch(err){toast(err.message)}};return false}return true}
async function renderInventory(){if(!retailerGate())return;try{rememberStore(bootstrap.user.store);$('#store-select').value=state.store;await loadProducts();const data={products:state.products,store:state.storeInfo};$('#content').innerHTML=head('Your collection, in one place.','Manage garments, stock and the size chart your shoppers use.','<button class="primary" id="add-product">+ Add garment</button>')+`<div class="toolbar"><button id="import-csv">Import CSV</button><a href="/api/inventory/template">Download CSV template</a><button id="edit-chart">Edit size chart</button></div><input type="file" id="csv-input" accept=".csv" hidden><div class="panel section-space"><div class="table-wrap"><table><thead><tr><th>Garment</th><th>SKU</th><th>Category</th><th>Price (PKR)</th><th>Stock</th><th>Sizes</th><th>Actions</th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.name)}${p.image?'':'<br><span class="subtle">Photo needed for try-on</span>'}</td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td><td>${p.price.toLocaleString()}</td><td>${p.stock}</td><td>${esc(p.sizes.join(', '))}</td><td><div class="row-actions"><button data-edit="${esc(p.id)}">Edit</button><button data-delete="${esc(p.id)}">Remove</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Your collection is empty. Add a garment or import a CSV.</td></tr>'}</tbody></table></div></div><div class="notice">CSV uploads update matching SKUs. Upload product photos through Edit after importing. Prices are in Pakistani rupees.</div>`;$('#add-product').onclick=()=>productDialog();$('#import-csv').onclick=()=>$('#csv-input').click();$('#csv-input').onchange=async e=>{if(!e.target.files[0])return;const form=new FormData();form.append('file',e.target.files[0]);try{const r=await api('/inventory/import',{method:'POST',body:form});toast(r.imported+' products imported.');await loadProducts();renderInventory()}catch(err){toast(err.message)}};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productDialog(data.products.find(p=>p.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{modal('Remove this garment?','<p>This hides the garment from the collection. Historical analytics are preserved.</p><button class="primary" id="confirm-remove">Remove garment</button>');$('#confirm-remove').onclick=async()=>{try{await api('/products/'+b.dataset.delete,{method:'DELETE'});$('#modal').close();await loadProducts();renderInventory()}catch(e){toast(e.message)}}});$('#edit-chart').onclick=()=>chartDialog(state.storeInfo)}catch(e){toast(e.message)}}
function productDialog(p={sizes:['S','M','L'],category:'upper',color:'#b7a58d',stock:0,price:0}){modal(p.id?'Edit garment':'Add a garment',`<form id="product-form"><div class="form-grid">${[['name','Garment name','text'],['sku','SKU','text'],['price','Price (PKR)','number'],['stock','Stock','number']].map(([key,label,type])=>`<label class="field">${label}<input name="${key}" type="${type}" value="${esc(p[key])}" ${key==='sku'&&p.id?'readonly':''} ${type==='number'?'min="0" step="'+(key==='price'?'0.01':'1')+'"':''} required></label>`).join('')}<label class="field">Category<select name="category">${['upper','lower','overall'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Color<input name="color" type="color" value="${esc(p.color)}"></label><label class="field">Top length<select name="upper_length"><option value="standard" ${(p.upper_length||'standard')==='standard'?'selected':''}>Standard top</option><option value="long" ${p.upper_length==='long'?'selected':''}>Long kurta / coat</option></select></label><label class="field full">Available sizes (separate with |)<input name="sizes" value="${esc(p.sizes.join('|'))}" required></label><label class="field full">Garment photo (JPEG / PNG)<input type="file" name="file" accept="image/jpeg,image/png"></label></div><button class="primary">Save garment</button><div class="inline-error" id="product-error"></div></form>`);const lengthField=$('#product-form [name=upper_length]'),categoryField=$('#product-form [name=category]');const syncLength=()=>{lengthField.closest('label').hidden=categoryField.value!=='upper';lengthField.closest('label').style.display=categoryField.value==='upper'?'':'none';lengthField.disabled=categoryField.value!=='upper'};categoryField.onchange=syncLength;syncLength();$('#product-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const form=new FormData(e.target);const body=Object.fromEntries(form);delete body.file;body.image=p.image||'';if(form.get('file').size){const upload=new FormData();upload.append('file',form.get('file'));upload.append('kind','garment');body.image=(await api('/uploads',{method:'POST',body:upload})).id}await api('/products',{method:'POST',body});$('#modal').close();await loadProducts();renderInventory()}catch(err){$('#product-error').textContent=err.message}finally{button.disabled=false}}}
function chartDialog(st){
 const charts=st.charts;
 modal('Category body-size charts',`<p>All measurements are in inches. Use full body circumferences, not flat garment widths. Starter charts are illustrative; replace them with your verified retailer chart. Optional columns can be left entirely blank.</p><div class="notice">Optional reference: EshalPreet Pakistani womenswear only. General body targets, not menswear or verified product fit. <a href="https://eshalpreet.com/pages/size-guide" target="_blank" rel="noopener">Source and scope</a><button type="button" id="load-reference">Load womenswear reference for review</button></div><form id="chart-form">${Object.keys(sizeRequired).map(category=>`<h3>${sizeLabels[category]}</h3><div class="table-wrap"><table><thead><tr><th>Size</th>${[...sizeRequired[category],...sizeOptional[category]].map(k=>`<th>${sizeLabels[k]}${sizeOptional[category].includes(k)?' (optional)':''}</th>`).join('')}</tr></thead><tbody>${['XS','S','M','L','XL','XXL'].map(size=>[size,charts[category][size]]).map(([size,row])=>`<tr><td>${esc(size)}</td>${[...sizeRequired[category],...sizeOptional[category]].map(k=>`<td><input class="chart-input" aria-label="${category} ${size} ${k}" name="${category}-${size}-${k}" type="number" min="${sizeLimits[k][0]}" max="${sizeLimits[k][1]}" step="0.01" value="${row[k]===undefined?'':Number(row[k].toFixed(2))}" ${sizeRequired[category].includes(k)?'required':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}<button class="primary">Save all charts</button><div class="inline-error" id="chart-error"></div></form>`);
 $('#load-reference').onclick=async()=>{try{const data=await api('/chart-presets');const preset=data.presets.find(p=>p.id==='eshalpreet-womenswear');if(!preset)throw new Error('Reference unavailable.');for(const c of ['upper','lower'])for(const size of ['XS','S','M','L','XL','XXL'])for(const k of [...sizeRequired[c],...sizeOptional[c]]){const input=document.querySelector(`[name="${c}-${size}-${k}"]`);input.value=preset.charts[c][size][k]??''}toast('Reference loaded for review. Confirm suitability, then save to apply.')}catch(e){$('#chart-error').textContent=e.message}};
 $('#chart-form').onsubmit=async e=>{e.preventDefault();const charts={upper:{},lower:{},overall:{}};for(const [key,value] of new FormData(e.target)){const [c,s,k]=key.split('-');charts[c][s]??={};if(value!=='')charts[c][s][k]=Number(value)}try{await api('/store/settings',{method:'PUT',body:{charts,chart_units:'in'}});await loadProducts();$('#modal').close();toast('Category charts saved.')}catch(err){$('#chart-error').textContent=err.message}};
}
function trendGraph(data,title){const entries=Object.entries(data).sort((a,b)=>a[0].localeCompare(b[0]));if(!entries.length)return '<div class="empty">No activity in this period yet.</div>';const start=new Date(entries[0][0]+'T00:00:00Z'),end=new Date(entries.at(-1)[0]+'T00:00:00Z'),points=[];for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+1)){const key=d.toISOString().slice(0,10);points.push([key,Number(data[key]||0)])}const max=Math.max(1,...points.map(p=>p[1])),xy=points.map((p,i)=>[40+i*520/Math.max(1,points.length-1),170-p[1]/max*140]);return `<div class="chart-body"><svg viewBox="0 0 600 210" role="img" aria-label="${esc(title)} chronological trend">${[0,0.5,1].map(v=>`<line x1="40" x2="560" y1="${170-v*140}" y2="${170-v*140}" stroke="#dce6e1"/><text x="4" y="${175-v*140}">${Number((v*max).toFixed(1))}</text>`).join('')}<polyline points="${xy.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#175c4d" stroke-width="3"/>${xy.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#175c4d"><title>${points[i][0]}: ${points[i][1]}</title></circle>`).join('')}<text x="40" y="200">${points[0][0]}</text><text x="560" y="200" text-anchor="end">${points.at(-1)[0]}</text></svg><details><summary>View chart values</summary>${bars(Object.fromEntries(points))}</details></div>`}
function shareGraph(data,labels){const entries=Object.entries(data).filter(([,v])=>v>0),total=entries.reduce((n,[,v])=>n+v,0);if(!total)return '<div class="empty">No category activity yet.</div>';const colors=['#175c4d','#65a994','#e5b969','#8a9dad'];let offset=0;return `<div class="chart-body category-chart"><svg viewBox="0 0 160 160" role="img" aria-label="Category share of real try-ons">${entries.map(([k,v],i)=>{const fraction=v/total*100,result=`<circle cx="80" cy="80" r="56" fill="none" stroke="${colors[i%4]}" stroke-width="22" pathLength="100" stroke-dasharray="${fraction} ${100-fraction}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"><title>${esc(labels[k]||k)}: ${v}</title></circle>`;offset+=fraction;return result}).join('')}<text x="80" y="80" text-anchor="middle" class="chart-total">${total}</text><text x="80" y="99" text-anchor="middle">try-ons</text></svg><ul>${entries.map(([k,v],i)=>`<li><i style="background:${colors[i%4]}"></i>${esc(labels[k]||k)}: <b>${v} (${(v/total*100).toFixed(1)}%)</b></li>`).join('')}</ul></div>`}
function bars(data,names={}){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...entries.map(x=>x[1]));return entries.length?'<div class="bars">'+entries.map(([k,v])=>`<div class="bar-row"><span>${esc(names[k]||k)}</span><div class="bar-track"><i style="width:${v/max*100}%"></i></div><span>${v}</span></div>`).join('')+'</div>':'<div class="empty">No activity in this period yet.</div>'}
function analyticsDetails(r){
 const labels={upper:'Upper Body',lower:'Lower Body',overall:'Full outfits',unknown:'Unknown category',mixed:'Mixed preferences'};
 return `<div class="two-col section-space">${['upper','lower','overall','unknown'].map(c=>[c,r.category_popularity[c]]).filter(([c,data])=>c!=='unknown'||Object.keys(data).length).map(([c,data])=>`<section class="panel"><div class="panel-head"><h2>${labels[c]} popularity</h2></div>${bars(data,r.product_names)}</section>`).join('')}<section class="panel"><div class="panel-head"><h2>Customer preferences</h2></div>${bars(r.customer_preferences,labels)}<p class="panel-body subtle">${r.preference_customers} signed-in customers grouped by their most tried category in this period; ties are mixed. ${r.untracked_tryons} older/untracked try-ons excluded. Counts describe observed choices, not demographic predictions.</p></section><section class="panel"><div class="panel-head"><h2>Category interest</h2></div>${shareGraph(r.category_interest,labels)}</section></div><section class="panel section-space"><div class="panel-head"><h2>Size model evaluation</h2></div>${['upper','lower'].map(c=>[c,r.evaluations[c]]).map(([c,e])=>`<div class="panel-body"><h3>${labels[c]}</h3>${e.available?`<p>${e.test_rows} independent test fittings. ${esc(e.scope)}</p><div class="table-wrap"><table><thead><tr><th>Model</th><th>Accuracy</th><th>Log loss</th><th>Calibration error</th></tr></thead><tbody>${Object.entries(e.metrics).map(([m,v])=>`<tr><td>${esc({rf:'Random Forest',knn:'KNN',ensemble_calibrated:'Calibrated ensemble'}[m])}</td><td>${(v.accuracy*100).toFixed(1)}%</td><td>${v.log_loss.toFixed(3)}</td><td>${v.ece.toFixed(3)}</td></tr>`).join('')}</tbody></table></div>`:`<p>Unavailable: ${esc(e.reason)} Chart fallback remains available; fitting confidence unavailable.</p>`}</div>`).join('')}</section>`;
}
function arrangeAnalytics(){
 const root=$('#content'),panels=[...root.querySelectorAll('.panel')];
 const find=title=>panels.find(p=>p.querySelector('h2')?.textContent===title);
 const group=(title,subtitle,items,wide=false)=>{const section=document.createElement('section');section.className='analytics-section';const heading=document.createElement('div');heading.className='analytics-section-heading';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=subtitle;heading.append(h,p);section.append(heading);const grid=document.createElement('div');grid.className=wide?'analytics-grid analytics-grid-three':'analytics-grid';items.filter(Boolean).forEach(item=>{item.classList.remove('section-space');grid.append(item)});section.append(grid);root.append(section)};
 group('Activity & sales trends','Real try-on activity alongside the illustrative sales week.',[find('Try-ons over time (UTC)'),find('Sales trend')]);
 group('Garment & customer insights','Understand what shoppers explore and which sizes are recommended.',[find('Most tried-on garments'),find('Category interest'),find('Customer preferences'),find('Recommended size distribution')]);
 group('Popularity by category','Compare garment demand within each collection.',[find('Upper Body popularity'),find('Lower Body popularity'),find('Full outfits popularity'),find('Unknown category popularity')],true);
 group('Retail records','Actual sales, returns and your comparison baseline.',[find('Return comparison & sales records')]);
 const last=root.lastElementChild;last.querySelector('.analytics-grid').classList.add('analytics-grid-full');
 group('Technical details','Model availability, runtime and measurement coverage.',[find('Size model evaluation'),find('Body-shape segments')]);
 const performance=[...root.children].find(n=>n.classList.contains('notice')&&n.textContent.includes('Model performance:'));if(performance)root.lastElementChild.append(performance);
 [...root.children].filter(n=>n.classList.contains('two-col')&&!n.children.length).forEach(n=>n.remove());
}
async function renderAnalytics(days=30){if(!retailerGate())return;$('#content').innerHTML='<div class="loading">Loading store insights…</div>';try{const r=await api('/analytics?days='+days);const catalog=await api('/products?store='+bootstrap.user.store);const names={...Object.fromEntries(catalog.products.map(p=>[p.id,p.name])),...r.product_names};$('#content').innerHTML=head('From try-on to insight.','Real activity from your store’s fitting room.',`<div class="toolbar"><select id="period" aria-label="Reporting period">${[7,30,90].map(d=>`<option value="${d}" ${d===days?'selected':''}>Last ${d} days</option>`).join('')}</select></div>`)+`<div class="notice sales-context"><span><strong>Sample sales metrics</strong> Sales, conversion and return rate illustrate a seven-day scenario. Completed try-ons and customer analytics use your real store activity.</span></div><div class="metrics analytics-metrics">${[['Completed try-ons',r.tryons,'Successful generations'],['Try-on conversion','32.5%','26 orders / 80 sample try-ons'],['Sales',r.sales_preview.orders,'Orders in the sample week'],['Return rate','7.7%','2 returns / 26 sample orders']].map(([title,value,note])=>`<div class="metric"><span>${title}</span><b>${value}</b><span>${note}</span></div>`).join('')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Most tried-on garments</h2></div>${bars(r.popular,names)}</section><section class="panel"><div class="panel-head"><h2>Recommended size distribution</h2></div>${bars(r.sizes)}</section><section class="panel"><div class="panel-head"><h2>Body-shape segments</h2></div>${Object.keys(r.segments).length?bars(r.segments):'<div class="empty">Unavailable: Upper/Lower forms do not collect all measurements needed for body-shape classification.</div>'}</section><section class="panel"><div class="panel-head"><h2>Try-ons over time (UTC)</h2></div>${trendGraph(r.trend,"Completed try-ons")}</section></div>${commerceDetails(r)}${analyticsDetails(r)}<div class="notice"><span><strong>Model performance:</strong> Average end-to-end generation ${r.inference_seconds===null?'unavailable':r.inference_seconds+' seconds'} · ${r.failed} failed attempts. Accuracy requires a labelled evaluation dataset; no accuracy claim is inferred from usage.</span></div><div class="panel section-space"><div class="panel-head"><h2>Return comparison & sales records</h2><div class="toolbar"><button id="baseline">Set baseline</button><button id="record-event" class="primary">Record sale / return</button></div></div><p class="panel-body subtle">Before AI-FIT: ${r.baseline===null?'no baseline entered':r.baseline.toFixed(1)+'% returns'}. Selected period: ${r.return_rate===null?'no sales data':r.return_rate+'% returns'}. ${r.baseline!==null&&r.return_rate!==null?'Change: '+(r.return_rate-r.baseline).toFixed(1)+' percentage points.':''} Returns and sales are events within this period, not a matched sales cohort; older sales may be returned now. This comparison is observational, not proof that AI-FIT caused a change.</p><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Reference / Try-on ID</th></tr></thead><tbody>${r.recent.map(e=>`<tr><td>${esc(e.kind)}</td><td>${new Date(e.time*1000).toLocaleDateString()}</td><td>${esc(e.reference||e.id)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Activity will appear here as customers use your store.</td></tr>'}</tbody></table></div></div>`;arrangeAnalytics();$('#period').onchange=e=>renderAnalytics(Number(e.target.value));$('#record-event').onclick=()=>eventDialog(days);$('#baseline').onclick=()=>{modal('Before AI-FIT',`<form id="baseline-form"><p class="subtle">Enter orders and returns from a comparable period before using AI-FIT.</p><label class="field">Orders<input type="number" name="baseline_orders" min="0" value="${r.store.baseline_orders}" required></label><label class="field">Returns<input type="number" name="baseline_returns" min="0" value="${r.store.baseline_returns}" required></label><button class="primary">Save baseline</button><div class="inline-error" id="baseline-error"></div></form>`);$('#baseline-form').onsubmit=async e=>{e.preventDefault();try{await api('/store/settings',{method:'PUT',body:Object.fromEntries(new FormData(e.target))});$('#modal').close();renderAnalytics(days)}catch(err){$('#baseline-error').textContent=err.message}}}}catch(e){$('#content').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function eventDialog(days){modal('Record a retail outcome',`<form id="event-form"><label class="field">Event<select name="kind"><option value="sale">Sale</option><option value="return">Return</option></select></label><label class="field">Order reference<input name="reference" required maxlength="100"></label><label class="field">Try-on ID (optional)<input name="tryon"></label><p class="subtle">Link the try-on ID shown under a customer’s generated image to measure conversion. Returns must use the original sale’s order reference.</p><button class="primary">Save record</button><div id="event-error" class="inline-error"></div></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();try{await api('/retail/events',{method:'POST',body:Object.fromEntries(new FormData(e.target))});$('#modal').close();renderAnalytics(days)}catch(err){$('#event-error').textContent=err.message}}}
function renderQr(){const sid=bootstrap.user?.store||state.store;$('#content').innerHTML=head('The fitting room comes to you.','Let shoppers use their own phone, or open a dedicated tablet session.')+`<div class="two-col"><section class="panel panel-body stack" style="text-align:center"><h2>Scan. Choose. Try on.</h2><img class="qr" src="/api/qr/${esc(sid)}" alt="QR code to this store’s fitting room"><a href="/api/qr/${esc(sid)}?download=1">Download store QR code</a><p class="subtle">For mobile scanning, configure PUBLIC_URL with your deployed HTTPS address. A localhost QR code only works on the host computer.</p></section><section class="panel panel-body stack"><h2>A fitting room for your tablet.</h2><p class="subtle">Kiosk mode provides a focused interface for in-store browsing. Each customer signs in to upload a photo. End the session between customers; inactivity signs out after two minutes.</p><a href="/kiosk?store=${esc(sid)}">Open tablet kiosk →</a><div class="notice">Personal photos are private to the signed-in account. Shared-device sessions clear the preview and sign out automatically.</div></section></div>`}
async function resetKiosk(){
  if(!bootstrap?.user||resetKiosk.pending)return;
  resetKiosk.pending=true;
  const photos=[state.photo?.id,state.result?.id].filter(Boolean);
  forgetGeneration();
  state.photo=null;
  state.result=null;state.fitError=null;
  state.view='fit';
  $('#modal').close();
  render();
  try{
    await Promise.allSettled(photos.map(id=>api('/uploads/'+id,{method:'DELETE'})));
    await logout();
  }catch(e){toast('Could not sign out. Select End session to retry.')}
  finally{resetKiosk.pending=false}
}
if(kiosk){const activity=()=>{clearTimeout(kioskTimer);kioskTimer=setTimeout(resetKiosk,120000)};['pointerdown','keydown'].forEach(e=>document.addEventListener(e,activity));activity()}
refresh().then(()=>{
  const token=new URLSearchParams(location.hash.slice(1)).get('reset');
  if(token){
    history.replaceState(null,'',location.pathname+location.search);
    passwordResetDialog(token);
  }
}).catch(e=>{$('#app').innerHTML=`<div class="empty">Could not open AI-FIT: ${esc(e.message)}. Refresh to retry.</div>`});

// Optional structured catalog access; authorization remains enforced by the server.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tools=[
  {name:'list_store_garments',description:'Read the current store catalog.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({store:state.store,products:state.products.map(({id,name,price,sizes})=>({id,name,price,sizes}))})},
  {name:'select_tryon_garment',description:'Select a garment in the visible fitting room. Does not upload a photo or generate an image.',inputSchema:{type:'object',properties:{productId:{type:'string'}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!state.products.some(p=>p.id===input?.productId))throw Error('Unknown garment in this store.');state.selected=input.productId;state.result=null;state.fitError=null;state.view='fit';render();return {selected:state.selected,view:state.view}}}
 ];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
